random.seed(1600)
def art(path,title,sub,seed):
    random.seed(seed); W,H=1600,1000
    im=Image.new('RGB',(W,H),(4,5,12)); px=im.load()
    for y in range(H):
      for x in range(W):
        r=math.hypot(x-W*.5,y-H*.48); a=max(0,1-r/950)
        n=random.random()*5
        px[x,y]=(int(5+18*a+n),int(6+9*a+n*.5),int(14+34*a+n))
    d=ImageDraw.Draw(im,'RGBA')
    for i in range(30):
      x=random.randint(0,W); y=random.randint(0,H); rr=random.randint(80,320)
      d.ellipse((x-rr,y-rr,x+rr,y+rr),fill=(80,55,180,random.randint(5,16)))
    d.rectangle((60,60,W-60,H-60),outline=(125,94,255,80),width=2)
    d.line((90,H-170,W-90,H-170),fill=(125,94,255,70),width=2)
    d.text((100,110),title,fill=(240,240,255,255))
    d.text((100,155),sub,fill=(155,145,190,230))
    for i in range(9):
      x=120+i*165; h=random.randint(80,330)
      d.rounded_rectangle((x,H-210-h,x+110,H-210),18,fill=(90,70,190,80),outline=(140,120,255,90),width=2)
    im.save(path,quality=92)
